-- 571: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 1 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_571_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_571_guard;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_035' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Your school is preparing a debate on the motion: "Boarding school is better than day school for senior high students." Answer the following planning questions.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) A speaker may speak for or against the motion; the speech opens with a vocative address such as "Mr Chairman, Panel of Judges, fellow students". (b) Boarding school gives students supervised prep time and freedom from long daily journeys, so they can focus fully on their studies.' AND q.explanation IS '(a) A motion has exactly two sides — for and against — and debate speeches open with the vocative address; (b) one clear sentence giving one reason for boarding school, with its result attached.' AND q.difficulty IS 'medium' AND q.points IS '10' AND q.marks IS '10' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Plan' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_035' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_035_a' AND NOT (sp.id IS 'sqp_q_eng_s3_035_a' AND sp.question_id IS 'q_eng_s3_035' AND sp.part_label IS 'a' AND sp.part_text IS 'State the two sides a speaker may take on this motion, and write out the vocative opening of a debate speech.' AND sp.marks IS '4' AND sp.correct_answer IS 'A speaker may speak for or against the motion; the speech opens with a vocative address such as "Mr Chairman, Panel of Judges, fellow students".' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_035_b' AND NOT (sp.id IS 'sqp_q_eng_s3_035_b' AND sp.question_id IS 'q_eng_s3_035' AND sp.part_label IS 'b' AND sp.part_text IS 'Write one sentence a speaker for the motion could use to state a first argument.' AND sp.marks IS '6' AND sp.correct_answer IS 'Boarding school gives students supervised prep time and freedom from long daily journeys, so they can focus fully on their studies.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_036' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer both questions. — "Mobile money has changed market trading in Tamale. Traders no longer carry large sums of cash, and buyers can settle even small debts instantly. Yet network failures sometimes strand traders who cannot reach their money, and fraudsters trick the careless into revealing their secret codes."' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Traders no longer carry large sums of cash, and buyers can settle even small debts instantly. (b) Network failures sometimes strand traders who cannot reach their money, and fraudsters trick the careless into revealing their secret codes.' AND q.explanation IS 'Both answers come straight from the passage: (a) the two conveniences and (b) the two risks, stated briefly without adding ideas of your own.' AND q.difficulty IS 'medium' AND q.points IS '10' AND q.marks IS '10' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Read' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_036' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_036_a' AND NOT (sp.id IS 'sqp_q_eng_s3_036_a' AND sp.question_id IS 'q_eng_s3_036' AND sp.part_label IS 'a' AND sp.part_text IS 'State two benefits of mobile money mentioned in the passage.' AND sp.marks IS '4' AND sp.correct_answer IS 'Traders no longer carry large sums of cash, and buyers can settle even small debts instantly.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_036_b' AND NOT (sp.id IS 'sqp_q_eng_s3_036_b' AND sp.question_id IS 'q_eng_s3_036' AND sp.part_label IS 'b' AND sp.part_text IS 'State two dangers of mobile money mentioned in the passage.' AND sp.marks IS '6' AND sp.correct_answer IS 'Network failures sometimes strand traders who cannot reach their money, and fraudsters trick the careless into revealing their secret codes.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_039' AND NOT (q.topic_id IS 'topic_wassce_english_oral' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Answer both questions on oral English.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Three syllables (com-mit-tee). (b) It turns the statement into a yes-no question, showing the speaker is asking for confirmation.' AND q.explanation IS '(a) "committee" divides into three syllables: com-mit-tee. (b) Rising intonation on a statement form signals a question expecting a yes or no answer, not a statement of fact.' AND q.difficulty IS 'medium' AND q.points IS '6' AND q.marks IS '6' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Answer' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_039' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_039_a' AND NOT (sp.id IS 'sqp_q_eng_s3_039_a' AND sp.question_id IS 'q_eng_s3_039' AND sp.part_label IS 'a' AND sp.part_text IS 'State the number of syllables in the word "committee".' AND sp.marks IS '2' AND sp.correct_answer IS 'Three syllables (com-mit-tee).' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_571_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_039_b' AND NOT (sp.id IS 'sqp_q_eng_s3_039_b' AND sp.question_id IS 'q_eng_s3_039' AND sp.part_label IS 'b' AND sp.part_text IS 'A speaker says "You are coming?" with a rising tone. State what the rising intonation shows.' AND sp.marks IS '4' AND sp.correct_answer IS 'It turns the statement into a yes-no question, showing the speaker is asking for confirmation.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
